	// symlinked files are kept only when their real target stays inside root.
	function* walk(base: string): Generator<{ rel: string; abs: string }> {
		const stat = statSync(base);
		if (stat.isFile()) {
			yield { rel: path.relative(root, base), abs: base };
			return;
		}
