		while (stack.length > 0) {
			const dir = stack.pop()!;
			for (const name of readdirSync(dir).sort()) {
				if (name === ".git") continue;
				const abs = path.join(dir, name);
				const entry = lstatSync(abs);
				if (entry.isDirectory()) {
					stack.push(abs);
